import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"技能触发器","description":"","frontmatter":{},"headers":[],"relativePath":"modules/mobs/triggers.md","filePath":"modules/mobs/triggers.md","lastUpdated":0}`),a={name:`modules/mobs/triggers.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="技能触发器" tabindex="-1">技能触发器 <a class="header-anchor" href="#技能触发器" aria-label="Permalink to “技能触发器”">​</a></h1><p>生物定义中的 <code>actions</code> 节点将触发器事件与 CoreLib 动作管道绑定。动作由 <strong>EmakiCoreLib</strong> 的动作管道执行（CoreLib 是硬依赖），<strong>不需要</strong>安装 EmakiSkills。旧键 <code>skills</code> 仍作为兼容回退，读取时会提示 WARN，建议迁移。</p><h2 id="触发器列表" tabindex="-1">触发器列表 <a class="header-anchor" href="#触发器列表" aria-label="Permalink to “触发器列表”">​</a></h2><table tabindex="0"><thead><tr><th>触发器</th><th>触发时机</th><th>上下文对象</th></tr></thead><tbody><tr><td><code>on_spawn</code></td><td>生物刷出（<code>MobFactory</code> 内，在 Boss 血条与模型挂载之后立即执行）</td><td>—</td></tr><tr><td><code>on_death</code></td><td>生物死亡</td><td><code>killer</code>（击杀者，仅在存在存活击杀者时提供）</td></tr><tr><td><code>on_target</code></td><td>生物锁定新目标</td><td><code>target</code>（仅在目标非空时提供）</td></tr><tr><td><code>on_damage_give</code></td><td>该生物作为攻击者造成伤害</td><td><code>target</code>（仅在受击者是生物实体时提供）</td></tr><tr><td><code>on_damage_take</code></td><td>该生物受到伤害</td><td><code>attacker</code>（仅在攻击者是生物实体时提供）</td></tr><tr><td><code>on_kill</code></td><td>生物击杀某实体</td><td><code>victim</code>（被击杀实体）</td></tr><tr><td><code>on_shoot</code></td><td>生物射出弹射物</td><td>—</td></tr><tr><td><code>on_explode</code></td><td>生物爆炸（如苦力怕）</td><td>—</td></tr><tr><td><code>on_teleport</code></td><td>生物传送</td><td>—</td></tr><tr><td><code>on_transform</code></td><td>生物变形（如僵尸猪灵变身）</td><td>—</td></tr><tr><td><code>on_health_threshold_&lt;百分比&gt;</code></td><td>生物血量首次降到该百分比及以下</td><td>—</td></tr></tbody></table><p>「上下文对象」列出的对象由 EmakiMobs 通过 CoreLib 的动作上下文键传入；未提供时对应的源段（如 <code>killer</code>）返回空结果，该动作行不会被选中执行。<strong>没有伤害量对象</strong>（<code>on_damage_give</code> / <code>on_damage_take</code> 都不提供 <code>damage</code>），需要伤害数值请改用 CoreLib 的其他手段。</p><h3 id="血量阈值触发器" tabindex="-1">血量阈值触发器 <a class="header-anchor" href="#血量阈值触发器" aria-label="Permalink to “血量阈值触发器”">​</a></h3><p><code>on_health_threshold_&lt;百分比&gt;</code> 的百分比档位是固定的五档，只有以下五个键名会被触发：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>on_health_threshold_90</span></span>
<span class="line"><span>on_health_threshold_75</span></span>
<span class="line"><span>on_health_threshold_50</span></span>
<span class="line"><span>on_health_threshold_25</span></span>
<span class="line"><span>on_health_threshold_10</span></span></code></pre></div><p>写其他数字（如 <code>on_health_threshold_80</code>）不会报错，但永远不会触发。</p><p>每个档位对同一只生物<strong>只触发一次</strong>。生物受到伤害时按 90 → 10 的顺序检查，一次伤害跨过多个档位时，被跨过的档位会在同一次伤害中依次触发。阈值以 <code>当前生命值 / 最大生命值属性值</code> 计算，最大生命值属性缺失或不为正时不做阈值检查。</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>血量阈值随伤害事件一并检测，因此 <code>on_damage_take</code> 与命中的阈值触发器会同时执行。</p></div><h2 id="动作字符串格式" tabindex="-1">动作字符串格式 <a class="header-anchor" href="#动作字符串格式" aria-label="Permalink to “动作字符串格式”">​</a></h2><p>每个触发器对应一组 CoreLib 动作管道字符串，格式为：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[选择器 |] 动作名 [参数=值 ...]</span></span></code></pre></div><h3 id="常用选择器" tabindex="-1">常用选择器 <a class="header-anchor" href="#常用选择器" aria-label="Permalink to “常用选择器”">​</a></h3><table tabindex="0"><thead><tr><th>选择器</th><th>来源</th><th>说明</th></tr></thead><tbody><tr><td><code>self</code></td><td>CoreLib</td><td>触发该事件的生物自身（管道施法者）。</td></tr><tr><td><code>target</code></td><td>EmakiMobs</td><td>当前事件的目标实体（<code>on_target</code>、<code>on_damage_give</code>）。</td></tr><tr><td><code>killer</code></td><td>EmakiMobs</td><td>击杀该生物的实体（<code>on_death</code>）。</td></tr><tr><td><code>victim</code></td><td>EmakiMobs</td><td>被该生物击杀的实体（<code>on_kill</code>）。</td></tr><tr><td><code>attacker</code></td><td>EmakiMobs</td><td>攻击该生物的实体（<code>on_damage_take</code>）。</td></tr><tr><td><code>nearby radius=&lt;n&gt; include_players=true</code></td><td>CoreLib</td><td>半径范围内的实体。<strong>玩家默认被排除</strong>：<code>include_players</code> 默认 <code>false</code>，只写 <code>type=player</code> 会选不出任何目标，必须显式加 <code>include_players=true</code>。</td></tr></tbody></table><p>四个 EmakiMobs 注册的选择器（<code>target</code> / <code>killer</code> / <code>victim</code> / <code>attacker</code>）依赖上文列出的上下文对象，只有在对应触发器的事件中存在该对象时才能解析出目标。</p><h3 id="动作示例" tabindex="-1">动作示例 <a class="header-anchor" href="#动作示例" aria-label="Permalink to “动作示例”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_spawn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 向附近 20 格内所有玩家发送消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nearby radius=20 include_players=true | send_message text=&#39;&lt;red&gt;精英僵尸降临！&#39;&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 在自身位置播放粒子效果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | spawn_particle particle=FLAME count=30 offset_x=0 offset_y=1 offset_z=0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_death</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 向击杀者给予经验</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;killer | give_exp amount=80&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 向附近玩家广播消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nearby radius=50 include_players=true | send_message text=&#39;&lt;green&gt;精英僵尸已被击败！&#39;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_give</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 对被攻击目标施加减速效果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target | give_potion_effect type=SLOWNESS level=1 duration=3s&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_take</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 受伤时在自身位置产生火焰粒子</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | spawn_particle particle=FLAME count=10 offset_x=0 offset_y=1 offset_z=0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 锁定目标时播放音效</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | play_sound sound=minecraft:entity.skeleton.ambient volume=1.0 pitch=0.7&quot;</span></span></code></pre></div><h2 id="emakimobs-注册的源段与动作段" tabindex="-1">EmakiMobs 注册的源段与动作段 <a class="header-anchor" href="#emakimobs-注册的源段与动作段" aria-label="Permalink to “EmakiMobs 注册的源段与动作段”">​</a></h2><p>除 CoreLib 内置内容外，EmakiMobs 向动作系统注册了 8 个段（启动日志会输出注册数量与期望值 8）：4 个源段 <code>attacker</code> / <code>killer</code> / <code>victim</code> / <code>target</code>，4 个动作段 <code>summon_mob</code> / <code>mob_play_animation</code> / <code>mob_stop_animation</code> / <code>mob_set_model</code>。动作行编译失败时会在控制台输出 <code>技能编译错误: mob=&lt;id&gt; trigger=&lt;触发器&gt; line=&lt;行号&gt; reason=&lt;原因&gt;</code>，该行被跳过，同触发器其他行继续执行。</p><h3 id="summon-mob-—-召唤生物定义" tabindex="-1"><code>summon_mob</code> — 召唤生物定义 <a class="header-anchor" href="#summon-mob-—-召唤生物定义" aria-label="Permalink to “summon_mob — 召唤生物定义”">​</a></h3><p>在目标位置召唤一只 EmakiMobs 生物定义。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>mob_id</code></td><td>string</td><td>是</td><td>无</td><td>已加载的生物定义 id（区分大小写）</td><td>要召唤的生物定义；缺失或空白按配置错误（<code>INVALID_CONFIG</code>）返回，未注册的 id 同样按配置错误返回。</td></tr><tr><td><code>count</code></td><td>int</td><td>否</td><td><code>1</code></td><td><code>≥ 1</code>（小于 1 按 1 处理）</td><td>召唤数量；逐个在目标位置生成。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_take</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 在自身位置召唤两只火焰守卫</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | summon_mob mob_id=fire_guardian count=2&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_health_threshold_50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 半血时在击杀者位置召唤一只随从</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;killer | summon_mob mob_id=boss_minion&quot;</span></span></code></pre></div><p>该动作需要目标能解析出位置（执行域为位置区域）。目标没有位置时返回 <code>skipped</code>；全部召唤都失败时返回 <code>INTERNAL_ERROR</code>。</p><h3 id="模型动作段" tabindex="-1">模型动作段 <a class="header-anchor" href="#模型动作段" aria-label="Permalink to “模型动作段”">​</a></h3><p><code>mob_play_animation</code>、<code>mob_stop_animation</code>、<code>mob_set_model</code> 的参数与行为见<a href="./models.html">实体模型与动画</a>的「动作段」一节。</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>动作字符串的完整语法和可用动作列表由 <strong>EmakiCoreLib</strong> 提供。请参阅 CoreLib 文档了解所有可用动作及其参数格式。</p></div>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};